package com.erudit.quiz.repository;import com.erudit.quiz.model.QuizModels.*;import java.util.*;import lombok.RequiredArgsConstructor;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;
@Repository @RequiredArgsConstructor public class QuizRepository {private final JdbcClient jdbc;
 public List<Quiz> list(){return jdbc.sql("SELECT id,title FROM quizzes WHERE status='PUBLISHED' ORDER BY title").query((r,n)->new Quiz(r.getObject("id",UUID.class),r.getString("title"))).list();}
 public Quiz daily(){return jdbc.sql("SELECT id,title FROM quizzes WHERE daily AND status='PUBLISHED' ORDER BY id LIMIT 1").query((r,n)->new Quiz(r.getObject("id",UUID.class),r.getString("title"))).single();}
 public Quiz create(String title,String prompt,List<String> options,int correct,String hint){UUID id=UUID.randomUUID();jdbc.sql("INSERT INTO quizzes(id,title) VALUES(:id,:title)").param("id",id).param("title",title).update();jdbc.sql("INSERT INTO quiz_questions(id,quiz_id,prompt,options,correct_index,hint) VALUES(:qid,:id,:prompt,:options,:correct,:hint)").param("qid",UUID.randomUUID()).param("id",id).param("prompt",prompt).param("options",String.join("|",options)).param("correct",correct).param("hint",hint).update();return new Quiz(id,title);}
 public Question question(UUID quiz){return jdbc.sql("SELECT * FROM quiz_questions WHERE quiz_id=:id ORDER BY id LIMIT 1").param("id",quiz).query((r,n)->new Question(r.getObject("id",UUID.class),quiz,r.getString("prompt"),List.of(r.getString("options").split("\\|")),r.getInt("correct_index"),r.getString("hint"))).single();}
 public Attempt start(UUID quiz,UUID user){var v=new Attempt(UUID.randomUUID(),quiz,user,"STARTED",null,0);jdbc.sql("INSERT INTO quiz_attempts(id,quiz_id,user_id,status) VALUES(:id,:quiz,:user,'STARTED')").param("id",v.id()).param("quiz",quiz).param("user",user).update();return v;}
 public Attempt attempt(UUID id){return jdbc.sql("SELECT * FROM quiz_attempts WHERE id=:id").param("id",id).query((r,n)->new Attempt(id,r.getObject("quiz_id",UUID.class),r.getObject("user_id",UUID.class),r.getString("status"),(Integer)r.getObject("score"),r.getInt("hints_used"))).single();}
 public Attempt hint(Attempt v){if(v.hintsUsed()>=2)throw new IllegalStateException("Hint limit reached");jdbc.sql("UPDATE quiz_attempts SET hints_used=hints_used+1 WHERE id=:id AND status='STARTED'").param("id",v.id()).update();return new Attempt(v.id(),v.quizId(),v.userId(),v.status(),v.score(),v.hintsUsed()+1);}
 public Attempt finish(Attempt v,int score){if(jdbc.sql("UPDATE quiz_attempts SET status='COMPLETED',score=:score WHERE id=:id AND status='STARTED'").param("score",score).param("id",v.id()).update()!=1)throw new IllegalStateException("Quiz already submitted");return new Attempt(v.id(),v.quizId(),v.userId(),"COMPLETED",score,v.hintsUsed());}
}
